def find_max(arr):
    max_val = arr[0]
    for i in range(len(arr)):
        if arr[i] > max_val:
            max_val = arr[i]
    return max_val

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def sum_list(lst):
    total = 0
    for item in lst:
        total = total + item
    return total

def reverse_string(s):
    result = ""
    for i in range(len(s) - 1, -1, -1):
        result += s[i]
    return result

